// NOTE: Main Better Auth configuration with magic link plugin for passwordless auth
import { components } from './_generated/api';
import { query } from './_generated/server';
import type { DataModel } from './_generated/dataModel';
import authSchema from './betterAuth/schema';
import { createClient, type GenericCtx } from '@convex-dev/better-auth';
import { convex } from '@convex-dev/better-auth/plugins';
import { magicLink } from 'better-auth/plugins';
import { betterAuth, type BetterAuthOptions } from 'better-auth';
import { createAuthMiddleware } from 'better-auth/api';
import authConfig from './auth.config';

const siteUrl = process.env.SITE_URL;
// NOTE: First 100 confirmed users get lifetime premium
const PREMIUM_USER_LIMIT = 100;

// NOTE: Component client with local schema for custom user fields (isPremium)
export const authComponent = createClient<DataModel, typeof authSchema>(
  components.betterAuth,
  {
    local: {
      schema: authSchema,
    },
    verbose: false,
  }
);

// NOTE: Send email via Resend HTTP API (not SDK - SDK has Node.js deps)
// PERF: Using fetch directly avoids mailparser/stream dependencies
async function sendEmailViaResend(
  to: string,
  subject: string,
  html: string
): Promise<void> {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    console.error('RESEND_API_KEY not configured');
    return;
  }

  console.log(`Sending magic link email to: ${to}`);

  try {
    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: 'benchmrk <onboarding@benchmrk.app>',
        to: [to],
        subject,
        html,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('Resend API error:', response.status, error);
    } else {
      const result = await response.json();
      console.log('Email sent successfully:', result);
    }
  } catch (error) {
    console.error('Failed to send email:', error);
  }
}

// NOTE: Creates typed Better Auth options - separated for schema generation
export const createAuthOptions = (ctx: GenericCtx<DataModel>) => {
  return {
    appName: 'benchmrk',
    baseURL: siteUrl,
    secret: process.env.BETTER_AUTH_SECRET,
    database: authComponent.adapter(ctx),
    // NOTE: Disable email/password - we only use magic links for waitlist
    emailAndPassword: {
      enabled: false,
    },
    // NOTE: Custom user fields for premium tracking
    user: {
      additionalFields: {
        isPremium: {
          type: 'boolean',
          required: false,
          defaultValue: false,
        },
        premiumClaimedAt: {
          type: 'number',
          required: false,
        },
      },
    },
    // NOTE: Hooks to grant premium status on magic link verification
    hooks: {
      after: createAuthMiddleware(async (hookCtx) => {
        // NOTE: Only process magic link verification endpoint
        if (hookCtx.path !== '/magic-link/verify') {
          return;
        }

        const newSession = hookCtx.context.newSession;
        if (!newSession) {
          return;
        }

        const userId = newSession.user.id;
        const adapter = hookCtx.context.adapter;

        // NOTE: Check if user already has premium (idempotency)
        const existingUser = await adapter.findOne<{ isPremium?: boolean }>({
          model: 'user',
          where: [{ field: 'id', value: userId }],
        });

        if (existingUser?.isPremium) {
          // NOTE: Already premium, no action needed
          return;
        }

        // NOTE: Count current premium users
        const premiumUsers = await adapter.findMany<{ isPremium?: boolean }>({
          model: 'user',
          where: [{ field: 'isPremium', value: true }],
        });

        const premiumCount = premiumUsers?.length ?? 0;

        // NOTE: Grant premium if under limit
        if (premiumCount < PREMIUM_USER_LIMIT) {
          await adapter.update({
            model: 'user',
            where: [{ field: 'id', value: userId }],
            update: {
              isPremium: true,
              premiumClaimedAt: Date.now(),
            },
          });

          console.log(
            `Granted premium to user ${userId}. Total premium users: ${premiumCount + 1}/${PREMIUM_USER_LIMIT}`
          );
        }
      }),
    },
    plugins: [
      // NOTE: Magic link plugin for passwordless auth
      magicLink({
        // NOTE: 24 hour expiry for waitlist confirmation links
        expiresIn: 60 * 60 * 24,
        sendMagicLink: async ({ email, url }) => {
          // NOTE: Must await in Convex actions - no dangling promises allowed
          await sendEmailViaResend(
            email,
            'Claim your lifetime premium membership - benchmrk',
            generateMagicLinkEmail(url)
          );
        },
      }),
      // NOTE: Required for Convex compatibility - must be last
      convex({ authConfig }),
    ],
  } satisfies BetterAuthOptions;
};

// NOTE: Better Auth Instance factory
export const createAuth = (ctx: GenericCtx<DataModel>) => {
  return betterAuth(createAuthOptions(ctx));
};

// NOTE: Helper function to get current authenticated user
export const getCurrentUser = query({
  args: {},
  handler: async (ctx) => {
    return authComponent.getAuthUser(ctx);
  },
});

